{"argv":["/bin/busybox","sh","-c",". /etc/hydo/prelude.sh; wait_quorum || { echo "no quorum within 60 s"; exit 2; }
ectl --endpoints=$EPS get --prefix k > /tmp/hydo/kv 2>/dev/null || { echo "range read failed"; exit 2; }
awk 'FILENAME == ARGV[1] { if (FNR % 2) k = $0; else v[k] = $0; next }
     { if (v["k" $1] != "v" $1) { print "acked put k" $1 " lost (read \"" v["k" $1] "\")"; bad = 1; exit } }
     END { if (bad) exit 1 }' /tmp/hydo/kv $HYDO_ACKED || exit 1
echo "acked=$(wc -l < $HYDO_ACKED) all readable"
"],"capture":3000,"env":["HOME=/","HYDO_ACKED=/tmp/hydo/acked","HYDO_FAILED=/tmp/hydo/failed","HYDO_LOG=/tmp/hydo/etcd3.log","HYDO_OUTCOMES=/tmp/hydo/outcomes","HYDO_STEPS=30","HYDO_SVC=etcd3","TERM=linux"],"id":47,"op":"run","v":1}
